FirstKPI.query:
q = load &quot;ForecastingData&quot;;
q = filter q by &#39;Type&#39; == &quot;Prediction&quot; &amp;&amp; &#39;Category&#39; == &quot;Prediction&quot; &amp;&amp; &#39;Owner_ID&#39; == &quot;!{user.Id}&quot; &amp;&amp; &#39;Period_ID&#39; == &quot;{{cell(CurrentPeriod.result, 0, &quot;Id&quot;).asString()}}&quot;;
q = foreach q generate &#39;Owner_ID&#39; as &#39;OwnerId&#39;, &#39;Value&#39; * {{coalesce(cell(CurrencyTypeStep.result, 0, &quot;ConversionRate&quot;), 1).asObject()}} as &#39;KPIValue1&#39;;
