b = load &quot;ForecastingData&quot;;b = filter b by &#39;Type&#39; == &quot;Prediction&quot; &amp;&amp; &#39;Category&#39; == &quot;Prediction&quot; &amp;&amp; &#39;Owner_ID&#39; == &quot;!{user.Id}&quot; &amp;&amp; &#39;Period_ID&#39; == &quot;{{cell(CurrentPeriod.result, 0, &quot;Id&quot;).asString()}}&quot;;
